import estate from './estate.json';

// estate.json is generated by scripts/import-demo.mjs (npm run import:demo).
// The units are sample data until the client supplies the real list.

export type UnitStatus = 'available' | 'reserved' | 'let';

export interface MonthlyRent {
  kes: number;
  usd: number;
}

export interface Unit {
  number: string;
  type: string;
  floor: number;
  sizeSqm: number;
  sizeSqft: number;
  bedrooms: number;
  bathrooms: number;
  status: UnitStatus;
  rentPerMonth: MonthlyRent | null;
}

export interface EstateItem {
  name: string;
  description: string;
}

export const RATES = estate.rates;
export const RENTS: Record<string, MonthlyRent> = estate.rents;
export const UNITS = estate.units as Unit[];

